SET LINES 250 PAGES 200 FEEDBACK OFF TRIMSPOOL ON
VARIABLE docn NUMBER
VARIABLE docs VARCHAR2(14)
VARIABLE ini VARCHAR2(10)
VARIABLE fim VARCHAR2(10)
VARIABLE limite NUMBER
VARIABLE deslocamento NUMBER
EXEC :docn := 11444777000161; :docs := '11444777000161'; :limite := 51; :deslocamento := 0;
ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD';
EXEC :ini := '2026-09-01'; :fim := '2026-10-01';
PROMPT ===== 1) ORIGINAL (FULL + TRUNC + bind numerico)
SELECT /* CH04_ORIGINAL */ COUNT(*) FROM (SELECT * FROM ( SELECT a.*, ROWNUM RN FROM (
  SELECT /*+ GATHER_PLAN_STATISTICS FULL(n) */ n.ID, n.PRESTADOR_ID, n.NUMERO, n.CODIGO_VERIFICACAO, n.DT_EMISSAO, n.COMPETENCIA, n.ITEM_SERVICO, n.DISCRIMINACAO, n.VALOR_SERVICOS, n.VALOR_DEDUCOES, n.BASE_CALCULO, n.ALIQUOTA, n.VALOR_ISS, n.ISS_RETIDO, n.TOMADOR_DOCUMENTO, n.TOMADOR_RAZAO, n.SITUACAO, n.DT_CANCELAMENTO, (SELECT s.NUMERO FROM NFSE s WHERE s.ID = n.NFSE_SUBSTITUIDORA_ID) AS NUM_SUBSTITUIDORA, p.DOCUMENTO AS PRESTADOR_DOC, p.INSCRICAO_MUNICIPAL AS PRESTADOR_IM, p.RAZAO_SOCIAL AS PRESTADOR_RAZAO
    FROM NFSE n JOIN CONTRIBUINTES p ON p.ID = n.PRESTADOR_ID
   WHERE n.TOMADOR_DOCUMENTO = :docn
     AND TRUNC(n.DT_EMISSAO) >= TO_DATE(:ini,'YYYY-MM-DD') AND TRUNC(n.DT_EMISSAO) < TO_DATE(:fim,'YYYY-MM-DD')
   ORDER BY n.DT_EMISSAO, n.ID ) a WHERE ROWNUM <= :limite) WHERE RN > :deslocamento);
SELECT plan_table_output FROM TABLE(DBMS_XPLAN.DISPLAY_CURSOR(
  (SELECT sql_id FROM v$sql WHERE sql_text LIKE '%/* CH04_ORIGINAL */%' AND sql_text NOT LIKE '%v$sql%' AND ROWNUM = 1), NULL, 'ALLSTATS LAST +PREDICATE -NOTE'));
SELECT buffer_gets, ROUND(elapsed_time/1000/executions,1) ms_por_exec FROM v$sql WHERE sql_text LIKE '%/* CH04_ORIGINAL */%' AND sql_text NOT LIKE '%v$sql%';
PROMPT ===== 2) PR-118 (INDEX hint + TRUNC + bind numerico)
SELECT /* CH04_PR118 */ COUNT(*) FROM (SELECT * FROM ( SELECT a.*, ROWNUM RN FROM (
  SELECT /*+ GATHER_PLAN_STATISTICS INDEX(n IX_NFSE_TOMADOR_DT) */ n.ID, n.PRESTADOR_ID, n.NUMERO, n.CODIGO_VERIFICACAO, n.DT_EMISSAO, n.COMPETENCIA, n.ITEM_SERVICO, n.DISCRIMINACAO, n.VALOR_SERVICOS, n.VALOR_DEDUCOES, n.BASE_CALCULO, n.ALIQUOTA, n.VALOR_ISS, n.ISS_RETIDO, n.TOMADOR_DOCUMENTO, n.TOMADOR_RAZAO, n.SITUACAO, n.DT_CANCELAMENTO, (SELECT s.NUMERO FROM NFSE s WHERE s.ID = n.NFSE_SUBSTITUIDORA_ID) AS NUM_SUBSTITUIDORA, p.DOCUMENTO AS PRESTADOR_DOC, p.INSCRICAO_MUNICIPAL AS PRESTADOR_IM, p.RAZAO_SOCIAL AS PRESTADOR_RAZAO
    FROM NFSE n JOIN CONTRIBUINTES p ON p.ID = n.PRESTADOR_ID
   WHERE n.TOMADOR_DOCUMENTO = :docn
     AND TRUNC(n.DT_EMISSAO) >= TO_DATE(:ini,'YYYY-MM-DD') AND TRUNC(n.DT_EMISSAO) < TO_DATE(:fim,'YYYY-MM-DD')
   ORDER BY n.DT_EMISSAO, n.ID ) a WHERE ROWNUM <= :limite) WHERE RN > :deslocamento);
SELECT plan_table_output FROM TABLE(DBMS_XPLAN.DISPLAY_CURSOR(
  (SELECT sql_id FROM v$sql WHERE sql_text LIKE '%/* CH04_PR118 */%' AND sql_text NOT LIKE '%v$sql%' AND ROWNUM = 1), NULL, 'ALLSTATS LAST +PREDICATE -NOTE'));
SELECT buffer_gets, ROUND(elapsed_time/1000/executions,1) ms_por_exec FROM v$sql WHERE sql_text LIKE '%/* CH04_PR118 */%' AND sql_text NOT LIKE '%v$sql%';
PROMPT ===== 3) PROPOSTA (sem hint, faixa de data, bind VARCHAR2)
SELECT /* CH04_PROPOSTA */ COUNT(*) FROM (SELECT * FROM ( SELECT a.*, ROWNUM RN FROM (
  SELECT /*+ GATHER_PLAN_STATISTICS  */ n.ID, n.PRESTADOR_ID, n.NUMERO, n.CODIGO_VERIFICACAO, n.DT_EMISSAO, n.COMPETENCIA, n.ITEM_SERVICO, n.DISCRIMINACAO, n.VALOR_SERVICOS, n.VALOR_DEDUCOES, n.BASE_CALCULO, n.ALIQUOTA, n.VALOR_ISS, n.ISS_RETIDO, n.TOMADOR_DOCUMENTO, n.TOMADOR_RAZAO, n.SITUACAO, n.DT_CANCELAMENTO, (SELECT s.NUMERO FROM NFSE s WHERE s.ID = n.NFSE_SUBSTITUIDORA_ID) AS NUM_SUBSTITUIDORA, p.DOCUMENTO AS PRESTADOR_DOC, p.INSCRICAO_MUNICIPAL AS PRESTADOR_IM, p.RAZAO_SOCIAL AS PRESTADOR_RAZAO
    FROM NFSE n JOIN CONTRIBUINTES p ON p.ID = n.PRESTADOR_ID
   WHERE n.TOMADOR_DOCUMENTO = :docs
     AND n.DT_EMISSAO >= TO_DATE(:ini,'YYYY-MM-DD') AND n.DT_EMISSAO < TO_DATE(:fim,'YYYY-MM-DD')
   ORDER BY n.DT_EMISSAO, n.ID ) a WHERE ROWNUM <= :limite) WHERE RN > :deslocamento);
SELECT plan_table_output FROM TABLE(DBMS_XPLAN.DISPLAY_CURSOR(
  (SELECT sql_id FROM v$sql WHERE sql_text LIKE '%/* CH04_PROPOSTA */%' AND sql_text NOT LIKE '%v$sql%' AND ROWNUM = 1), NULL, 'ALLSTATS LAST +PREDICATE -NOTE'));
SELECT buffer_gets, ROUND(elapsed_time/1000/executions,1) ms_por_exec FROM v$sql WHERE sql_text LIKE '%/* CH04_PROPOSTA */%' AND sql_text NOT LIKE '%v$sql%';
EXIT
